<?php
declare(strict_types=1);
namespace Cbt\Core;
final class Response { public function __construct(private string $body='',private int $status=200,private array $headers=[]){} public static function json(mixed $data,string $message='',int $status=200):self{return new self(json_encode(['success'=>$status<400,'data'=>$data,'message'=>$message],JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE),$status,['Content-Type'=>'application/json; charset=utf-8']);} public static function error(string $message,int $status=400,array $errors=[]):self{return new self(json_encode(['success'=>false,'message'=>$message,'errors'=>$errors],JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE),$status,['Content-Type'=>'application/json; charset=utf-8']);} public static function html(string $html):self{return new self($html,200,['Content-Type'=>'text/html; charset=utf-8']);} public function send():never{http_response_code($this->status);foreach($this->headers as$n=>$v)header($n.': '.$v);echo$this->body;exit;} }
